From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition equality_core_text : string := "".
Definition equality_core_nodes :=
 match Wire.decode_text equality_core_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition equality_core_decode := match equality_core_nodes with
 | Some xs => definitions 500 (firstn 4 (skipn 0 xs)) | None => None end.
Definition equality_core_program := Eval vm_compute in
 match equality_core_decode with Some ds => ds | None => [] end.
Theorem equality_core_exact : equality_core_decode = Some equality_core_program.
Proof. vm_compute. reflexivity. Qed.
Theorem equality_core_names : map fst equality_core_program = ["kl:buri.eq2-derive";"kl:buri.eq2-sym";"kl:buri.eq2-trans";"kl:buri.eq2-cong"].
Proof. vm_compute. reflexivity. Qed.
Theorem equality_core_complete : match equality_core_nodes with
 | Some xs => List.length xs = 4 | None => False end.
Proof. vm_compute; reflexivity. Qed.
Global Opaque equality_core_text equality_core_nodes equality_core_decode.
